//! Stdio ↔ HTTP bridge for Xcord's MCP server.
//!
//! MCP clients such as Claude Desktop and Cursor launch this binary and speak
//! newline-delimited JSON-RPC on stdin/stdout. Each message is forwarded to the
//! running Xcord app (`POST http://127.0.0.1:8765/mcp`) with the local bearer
//! token generated by the app.
//!
//! Environment overrides:
//!   XCORD_MCP_URL    full URL (default http://127.0.0.1:8765/mcp)
//!   XCORD_MCP_TOKEN  bearer token (default: read `<config>/mcp-token`)

use std::io::{BufRead, BufReader, Read, Write};
use std::net::TcpStream;
use std::time::Duration;

fn main() {
    let mut url =
        std::env::var("XCORD_MCP_URL").unwrap_or_else(|_| "http://127.0.0.1:8765/mcp".to_string());
    let mut token = std::env::var("XCORD_MCP_TOKEN").unwrap_or_default();
    let mut args = std::env::args().skip(1);
    while let Some(arg) = args.next() {
        match arg.as_str() {
            "--url" => url = args.next().unwrap_or(url),
            "--token" => token = args.next().unwrap_or(token),
            "--help" | "-h" => {
                eprintln!("xcord-mcp [--url URL] [--token TOKEN]");
                return;
            }
            _ => {}
        }
    }
    if token.is_empty() {
        token = read_token().unwrap_or_default();
    }
    if token.is_empty() {
        eprintln!("xcord-mcp: missing token; run Xcord once so it can create mcp-token");
        std::process::exit(1);
    }

    let (host, port, path) = match parse_url(&url) {
        Some(parts) => parts,
        None => {
            eprintln!("xcord-mcp: only http:// URLs are supported: {url}");
            std::process::exit(1);
        }
    };

    let stdin = std::io::stdin();
    let mut stdout = std::io::stdout();
    for line in BufReader::new(stdin.lock()).lines() {
        let Ok(line) = line else { break };
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        match post(&host, port, &path, &token, line) {
            Ok(Some(body)) => {
                let _ = writeln!(stdout, "{body}");
                let _ = stdout.flush();
            }
            Ok(None) => {}
            Err(error) => {
                eprintln!("xcord-mcp: {error}");
                // Return a valid JSON-RPC error so the client is not left
                // hanging if the app is down.
                let id = jsonrpc_id(line);
                let _ = writeln!(
                    stdout,
                    "{{\"jsonrpc\":\"2.0\",\"id\":{id},\"error\":{{\"code\":-32603,\"message\":{}}}}}",
                    json_string(&error)
                );
                let _ = stdout.flush();
            }
        }
    }
}

fn read_token() -> Option<String> {
    let path = xcord_store::config_dir().join("mcp-token");
    std::fs::read_to_string(path)
        .ok()
        .map(|token| token.trim().to_string())
}

fn parse_url(url: &str) -> Option<(String, u16, String)> {
    let rest = url.strip_prefix("http://")?;
    let (authority, path) = match rest.split_once('/') {
        Some((authority, path)) => (authority, format!("/{path}")),
        None => (rest, "/mcp".into()),
    };
    let (host, port) = match authority.rsplit_once(':') {
        Some((host, port)) => (host.to_string(), port.parse().ok()?),
        None => (authority.to_string(), 80),
    };
    if host.is_empty() {
        return None;
    }
    Some((host, port, path))
}

fn post(
    host: &str,
    port: u16,
    path: &str,
    token: &str,
    body: &str,
) -> Result<Option<String>, String> {
    let mut stream = TcpStream::connect((host, port)).map_err(|error| {
        format!("cannot reach Xcord at {host}:{port} ({error}); is the app running?")
    })?;
    let _ = stream.set_read_timeout(Some(Duration::from_secs(180)));
    let _ = stream.set_write_timeout(Some(Duration::from_secs(30)));
    let request = format!(
        "POST {path} HTTP/1.1\r\nHost: {host}:{port}\r\nAuthorization: Bearer {token}\r\nContent-Type: application/json\r\nAccept: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
        body.len()
    );
    stream
        .write_all(request.as_bytes())
        .map_err(|error| error.to_string())?;
    stream.flush().map_err(|error| error.to_string())?;

    let mut response = Vec::new();
    stream
        .read_to_end(&mut response)
        .map_err(|error| error.to_string())?;
    let split = response
        .windows(4)
        .position(|window| window == b"\r\n\r\n")
        .ok_or_else(|| "malformed HTTP response".to_string())?;
    let headers = String::from_utf8_lossy(&response[..split]);
    let status = headers
        .lines()
        .next()
        .and_then(|line| line.split_whitespace().nth(1))
        .and_then(|code| code.parse::<u16>().ok())
        .unwrap_or(0);
    let body = String::from_utf8_lossy(&response[split + 4..]).to_string();

    if status == 202 || body.trim().is_empty() {
        return Ok(None);
    }
    if !(200..300).contains(&status) {
        return Err(format!("HTTP {status}: {body}"));
    }
    Ok(Some(body))
}

fn jsonrpc_id(line: &str) -> String {
    // Cheap, dependency-free extraction of a numeric or string id.
    if let Some(index) = line.find("\"id\"") {
        let rest = &line[index + 4..];
        if let Some(colon) = rest.find(':') {
            let rest = rest[colon + 1..].trim_start();
            let end = rest
                .find(|ch: char| ch == ',' || ch == '}')
                .unwrap_or(rest.len());
            let id = rest[..end].trim();
            if !id.is_empty() {
                return id.to_string();
            }
        }
    }
    "null".into()
}

fn json_string(value: &str) -> String {
    let mut out = String::with_capacity(value.len() + 2);
    out.push('"');
    for ch in value.chars() {
        match ch {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            ch if ch.is_control() => out.push_str(&format!("\\u{:04x}", ch as u32)),
            ch => out.push(ch),
        }
    }
    out.push('"');
    out
}
